<script setup lang="ts">
import {useFixedDockHeight} from '../../shared/composables/useFixedDockHeight';
import Icon from '../../shared/Icon.vue';
import MeetingInfoEditor from '../meetings/MeetingInfoEditor.vue';
import {usePublicationConfiguration} from './usePublicationConfiguration';
import {usePublicationDestinations} from './usePublicationDestinations';
import FinalConfirmationChecks from './FinalConfirmationChecks.vue';
import {finalConfirmationChecks,type FinalCheckTarget} from './final-confirmation-checks';
import {useFinalConfirmation} from './useFinalConfirmation';
import {canPrepareFinalInformation} from './final-information';
import {computed,shallowRef,ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import {usePublication} from './usePublication';import type {SavedMeeting} from '../../shared/api/meeting-info';import type {MinutesCurrent} from '../../shared/api/minutes-saved';import type {components} from '../../shared/api/generated';import {ApiError} from '../../shared/api/client';
const props=defineProps<{meetingId:string;owner:boolean;locked:boolean;targetLabels?:Record<string,string>;categoryLabels?:Record<string,string>;meetingInfo?:SavedMeeting;savedMinutes?:MinutesCurrent;stage?:string}>();const emit=defineEmits<{changed:[];denied:[cause:unknown];editInfo:[];published:[];infoSaved:[];navigate:[stage:string];process:[target:FinalCheckTarget]}>();const app=useApplication();
const p=usePublication({...app.publications,authorize:async(id,s)=>{const n=await app.workspace.navigation(id,s);return n.relation!=='OWNER'?false:n.navigationState==='PUBLISHED_READ_ONLY'?'READ_ONLY':n.navigationState==='CHECK_PRODUCER';}},()=>app.session.current.value?.actor.enterpriseId??null,()=>props.meetingId,()=>props.owner,()=>app.minutesScopeReady.value,()=>props.locked,app.journals,cause=>{clear();emit('denied',cause);});
const canPrepareFinal=computed(()=>canPrepareFinalInformation(p.readiness.value));
const embeddedInfo=ref<InstanceType<typeof MeetingInfoEditor>>(),successDialog=ref<HTMLDialogElement>(),submitted=ref(false),successShown=ref(false);let pollEpoch=0,pollTimer:ReturnType<typeof setTimeout>|null=null;
const librarySearch=ref(''),error=ref(''),reading=ref(false),optional=ref<string[]>([]),attempts=shallowRef<components['schemas']['AttemptPage']|null>(null);let epoch=0,controller:AbortController|null=null;
const remoteLabels:Record<string,string>={SUCCESS:'知识库已保存',FAILED:'知识库已拒绝',UNKNOWN:'结果待查回',NOT_OBSERVED:'尚未确认'};
const applicationLabels:Record<string,string>={FENCED_MANUAL:'发布关联待处理',PENDING_LOOKUP:'正在查回发布结果',APPLIED:'已应用',PENDING:'等待应用',DISCARDED:'未应用',FAILED:'应用失败',NOT_APPLIED:'尚未应用'};
const phaseLabels:Record<string,string>={VALIDATING:'校验确认版本、来源关系与发布权限',CREATING_DOCUMENT:'创建正式知识文档',WRITING_RECORDS:'写入发布记录及关联关系',COMPLETED:'发布完成',FAILED:'发布未完成'};
const failureLabels:Record<string,string>={DESTINATION_DENIED:'目标知识库拒绝了发布，请检查目录与发布权限。',UNKNOWN_OUTCOME:'结果尚未确定，请查询原任务。',PROVENANCE_UNAVAILABLE:'来源或确认关系暂不可核实，请重新核对。',PREPARATION_EXHAUSTED:'发布准备未完成，可恢复未发送任务。',CAPABILITY_UNAVAILABLE:'当前发布条件已变化，请核对确认与目标位置。'};
const attemptLabels:Record<string,string>={PUBLISH:'提交发布',RECONCILE:'查回发布结果',WITHDRAW:'撤回',OBSOLETE:'废止'};
const stateLabels:Record<string,string>={READY:'等待发布',RUNNING:'正在发布',RECONCILING:'正在查回结果',FAILED:'发布失败',SUCCEEDED:'已发布'};
const status=computed(()=>p.current.value?.publication),message=computed(()=>p.error.value instanceof Error?p.error.value.message:'发布状态暂不可用。');
const canManage=ref(false);let capabilityRequest:AbortController|null=null;
watch(()=>[app.session.current.value?.actor.enterpriseId,status.value?.publicationId,status.value?.rawState],async()=>{capabilityRequest?.abort();canManage.value=false;if(status.value?.rawState!=='SUCCEEDED'||!app.governance?.capabilities)return;const request=new AbortController();capabilityRequest=request;try{const value=await app.governance.capabilities(props.meetingId,status.value.publicationId,request.signal);if(!request.signal.aborted)canManage.value=value.canManage;}catch{canManage.value=false;}});
onUnmounted(()=>capabilityRequest?.abort());
const configuration=usePublicationConfiguration(app.publications,()=>app.session.current.value?.actor.enterpriseId??null,()=>props.meetingId);
const canReconfigure=computed(()=>!status.value||status.value.allowedActions.includes('RESUBMIT'));
const publicationPending=computed(()=>!!status.value&&!canReconfigure.value);
const configurationLocked=computed(()=>props.locked||!canReconfigure.value||p.busy.value||configuration.busy.value);
const destinations=usePublicationDestinations(app.publications,()=>app.session.current.value?.actor.enterpriseId??null,()=>props.meetingId,()=>props.owner&&app.minutesScopeReady.value,()=>configurationLocked.value,cause=>p.deny(cause),app.journals);
const selectedDestination=destinations.selection,previewDialog=ref<HTMLDialogElement>(),publicationSaveMessage=ref('');
const submittedConfiguration=computed(()=>status.value?.configurationSnapshot);
const shownConfiguration=computed(()=>publicationPending.value?submittedConfiguration.value:configuration.current.value?.configuration??submittedConfiguration.value);
const selectedPath=computed(()=>selectedDestination.value&&canReconfigure.value?[selectedDestination.value.libraryName,...selectedDestination.value.path.map(f=>f.name)].join(' / '):shownConfiguration.value?.pathNames.join(' / ')??(status.value?.libraryId?[status.value.libraryId,status.value.folderId].filter(Boolean).join(' / '):'请选择发布位置'));
const visibility=computed(()=>selectedDestination.value&&canReconfigure.value?selectedDestination.value.visibility??'正在核实目标知识库可见范围':shownConfiguration.value?.visibility??'选择知识库后显示实际可见范围');
const libraryLink=computed(()=>{const id=status.value?.libraryId??shownConfiguration.value?.libraryId;return id?'/meeting-library/'+encodeURIComponent(id)+'?meeting='+encodeURIComponent(props.meetingId):null;});
const configurationError=computed(()=>configuration.error.value instanceof Error?configuration.error.value.message:'发布配置暂不可读取或保存，请重试。');
const configurationChanged=computed(()=>{const frozen=submittedConfiguration.value,selected=selectedDestination.value;if(!frozen)return false;try{return !!selected&&(selected.libraryId!==frozen.libraryId||selected.folderId!==frozen.folderId)||JSON.stringify(configuration.tags())!==JSON.stringify(frozen.tags);}catch{return true;}});
async function loadConfiguration(){const who=app.session.current.value?.actor.enterpriseId,id=props.meetingId,value=await configuration.load();if(who!==app.session.current.value?.actor.enterpriseId||id!==props.meetingId||!value)return;if(value.configuration)await destinations.restoreSaved(value.configuration);else await destinations.loadLibraries();}

async function openPreview(){const actor=app.session.current.value?.actor.enterpriseId,id=props.meetingId;await p.reload();if(actor!==app.session.current.value?.actor.enterpriseId||id!==props.meetingId||!p.final.value?.confirmation||!p.final.value.body||!p.final.value.information||p.error.value)return;previewDialog.value?.showModal();}
watch(()=>p.final.value?.confirmation?.id,()=>{previewDialog.value?.close();emit('changed');});
watch(()=>status.value,value=>{if(value?.rawState==='SUCCEEDED'&&value.remoteOutcome==='SUCCESS'&&value.applicationOutcome==='APPLIED'){emit('published');if(!successShown.value&&(submitted.value||p.command.snapshot.value?.operation.startsWith('PUBLICATION_'))){successShown.value=true;successDialog.value?.showModal();}}});
async function read<T>(fn:(s:AbortSignal)=>Promise<T>,accept:(v:T)=>void){const turn=++epoch;controller?.abort();const request=new AbortController();controller=request;reading.value=true;error.value='';try{const v=await fn(request.signal);if(turn===epoch)accept(v);}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status)){p.deny(cause);}error.value=cause instanceof Error?cause.message:'目录暂不可用。';}}finally{if(turn===epoch)reading.value=false;}}
function clear(){configuration.clear();successDialog.value?.close();submitted.value=false;successShown.value=false;publicationSaveMessage.value='';previewDialog.value?.close();destinations.clear();librarySearch.value='';epoch++;controller?.abort();optional.value=[];attempts.value=null;error.value='';reading.value=false;}
async function run(fn:()=>Promise<void>){try{await fn();if(!p.error.value)emit('changed');}catch(cause){error.value=cause instanceof Error?cause.message:'操作暂不可用。';}}
async function publish(){const selected=selectedDestination.value;if(!selected||!destinations.canSubmit.value){error.value='请先核对真实知识库或文件夹。';return;}if(!await saveConfiguration())return;submitted.value=true;const target={providerId:selected.providerId,libraryId:selected.libraryId,folderId:selected.folderId,configurationVersionToken:configuration.current.value!.configurationVersionToken};await run(()=>status.value?p.recover('RESUBMIT',target):p.submit(target));}
function recover(action:'RETRY_ZERO_EFFECT'|'RECOVER_LOCAL'){submitted.value=true;void run(()=>p.recover(action));}

function loadAttempts(cursor:string|null=null){const id=status.value?.publicationId;if(id)void read(s=>app.publications.attempts(props.meetingId,id,cursor,s),v=>attempts.value=v);}
function reloadForStage(){if(!app.session.current.value)return;p.restoreOriginal();if(!props.stage||['confirm','publish','published'].includes(props.stage)||props.savedMinutes?.observation.readOnlyReason==='PUBLISHED'||p.command.snapshot.value)void p.reload();}
const stop=watch(()=>[app.session.current.value?.actor.enterpriseId,props.meetingId,props.owner,app.minutesScopeReady.value],()=>{clear();reloadForStage();},{immediate:true,flush:'sync'});onUnmounted(()=>{pollEpoch++;if(pollTimer)clearTimeout(pollTimer);stop();clear();configuration.dispose();destinations.dispose();p.dispose();});

watch(()=>[status.value?.publicationId,status.value?.currentTaskId,status.value?.executionNoToken,status.value?.rawState],()=>{const turn=++pollEpoch;if(pollTimer)clearTimeout(pollTimer);async function tick(){if(turn!==pollEpoch||!status.value)return;if(['READY','RUNNING','RECONCILING'].includes(status.value.rawState)||status.value.lookupPending){await p.refreshStatus();if(turn===pollEpoch)pollTimer=setTimeout(tick,2500);}}if(status.value)pollTimer=setTimeout(tick,1500);});
let searchTimer:ReturnType<typeof setTimeout>|null=null;
watch(librarySearch,value=>{if(searchTimer)clearTimeout(searchTimer);if(configurationLocked.value)return;searchTimer=setTimeout(()=>void destinations.loadLibraries(null,value.trim()),250);});
onUnmounted(()=>{if(searchTimer)clearTimeout(searchTimer);});

watch(()=>props.stage,reloadForStage);
watch(()=>props.savedMinutes?.observation.readOnlyReason,reason=>{if(reason==='PUBLISHED'&&props.stage&&!['confirm','publish','published'].includes(props.stage))reloadForStage();});
const visibleLibraries=computed(()=>destinations.libraries.value?.items??[]);
const finalFlow=useFinalConfirmation({
 validate:()=>!!embeddedInfo.value?.validateInformation(),
 information:async()=>await embeddedInfo.value?.saveFinalInformation()??false,
 roster:async()=>await embeddedInfo.value?.confirmFinalRoster()??false,
 readiness:async()=>{await p.reload();if(p.error.value)return false;if(!p.readiness.value?.ready){error.value='请处理确认检查中尚未完成的项目。';return false;}return true;},
 confirmation:async()=>{await p.confirm(optional.value);return !!p.final.value?.confirmation&&!p.error.value&&p.command.state.value==='ACKNOWLEDGED';},
 complete:()=>emit('navigate','publish')
});
watch(()=>[app.session.current.value?.actor.enterpriseId,props.meetingId],()=>finalFlow.invalidate(),{flush:'sync'});
watch(()=>[p.readiness.value?.observation?.revisionToken,embeddedInfo.value,finalFlow.busy.value,p.busy.value],()=>{const token=p.readiness.value?.observation?.revisionToken;if(token&&embeddedInfo.value&&!finalFlow.busy.value&&!p.busy.value&&embeddedInfo.value.revisionToken&&embeddedInfo.value.revisionToken!==token)void embeddedInfo.value.reload();});
onUnmounted(finalFlow.dispose);
async function confirmFinal(){error.value='';await finalFlow.confirm();if(finalFlow.error.value)error.value=finalFlow.error.value instanceof Error?finalFlow.error.value.message:'确认暂未完成，请核对当前状态。';}
async function beforeLeave(){if(finalFlow.busy.value||p.busy.value||['PREPARED','SENDING','UNCERTAIN','DENIED'].includes(p.command.state.value)){error.value='最终确认或发布结果尚未核实，请先查回原操作。';return false;}return await embeddedInfo.value?.beforeLeave()??true;}
watch(()=>[props.stage,p.final.value?.confirmation?.id,status.value?.publicationId,canReconfigure.value,props.owner,app.minutesScopeReady.value,props.locked],()=>{if(props.stage==='publish'&&props.owner&&app.minutesScopeReady.value&&!props.locked&&p.final.value?.confirmation&&canReconfigure.value&&!configuration.current.value&&!configuration.busy.value&&!configuration.error.value)void loadConfiguration();});

const canSaveInformation=computed(()=>props.stage==='confirm'&&props.owner&&!props.locked&&!!embeddedInfo.value?.canPrepare&&!finalFlow.busy.value&&!p.busy.value);
async function saveInformation(){return canSaveInformation.value?(await embeddedInfo.value?.saveInformation())??false:false;}
const canSaveConfiguration=computed(()=>props.stage==='publish'&&props.owner&&app.minutesScopeReady.value&&!configurationLocked.value&&!destinations.busy.value&&!destinations.error.value&&!!configuration.current.value);
async function saveConfiguration(){if(!canSaveConfiguration.value)return false;const selected=selectedDestination.value;if(!selected){publicationSaveMessage.value='尚未选择有效发布位置';return false;}const saved=await configuration.save(selected);publicationSaveMessage.value=saved?'发布配置已保存，可在其他会话恢复':'发布配置暂未保存，当前输入已保留';return saved;}

defineExpose({beforeLeave,informationDirty:computed(()=>embeddedInfo.value?.dirty??false),saveConfiguration,canSaveConfiguration,publicationSaveMessage,saveInformation,canSaveInformation,informationSaveMessage:computed(()=>embeddedInfo.value?.informationSaveMessage??'')});
const checks=computed(()=>finalConfirmationChecks(p.readiness.value,props.owner,props.targetLabels??{}));
const previewBody=computed(()=>p.final.value?.confirmation?p.final.value.body:props.savedMinutes?.body);
const previewBackground=computed(()=>p.final.value?.confirmation?(p.final.value.background??[]):(props.savedMinutes?.background??[]));
watch(()=>p.readiness.value?.optionalReviewIds,ids=>{optional.value=optional.value.filter(id=>ids?.includes(id));});
const optionalReviews=computed(()=>p.readiness.value?.optionalReviews??[]);
function optionalLabel(review:(typeof optionalReviews.value)[number]){return (review.targetKind==='BODY'?'纪要正文':props.targetLabels?.[review.targetId]??'成果内容')+' · '+(review.reviewKind==='ACTION_FIELDS'?'行动字段确认':'来源支持核对')+' · '+(review.targetAnchor?'指定内容范围':'完整目标')+' · 已通过';}
const previewElements=computed(()=>p.final.value?.confirmation?p.final.value.elements:props.savedMinutes?.elements);
const outcomeLabels:Record<string,string>={OVERVIEW:'会议概述',DISCUSSION:'关键内容',CONCLUSION:'会议结论',ACTION:'行动项',RISK:'风险与阻碍',OPEN_QUESTION:'待确认事项',DISAGREEMENT:'分歧'};
const shownInfo=computed(()=>p.final.value?.confirmation&&p.final.value.information?{...p.final.value.information,confirmedRosterId:p.final.value.information.rosterRevisionId,confirmedRoster:p.final.value.information.roster}:props.meetingInfo);
async function processCheck(target:FinalCheckTarget){if(target.kind==='retry'){await p.reload();return;}if(target.kind==='information'){if(!embeddedInfo.value)return;if(!embeddedInfo.value.validateInformation())return;embeddedInfo.value.focusField(target.field??'name');return;}emit('process',target);}
const fixedDock=ref<HTMLElement>();useFixedDockHeight(fixedDock);
</script>
<template><section class="publication" :class="{'m19-published-summary':stage==='published'}"><p v-if="p.error.value" role="alert">{{message}}</p><p v-if="error" role="alert">{{error}}</p>
 <template v-if="stage==='confirm'"><p v-if="p.reading.value" role="status" class="small muted">正在读取确认检查…</p><p v-else-if="p.error.value" role="alert"><button class="btn" @click="p.reload">重新读取确认检查</button></p><div class="ac-confirm-grid"><section class="card ac-confirm-info"><div class="card-h"><h3 class="card-t">会议信息</h3></div><div class="card-p"><MeetingInfoEditor v-if="owner&&savedMinutes?.observation.readOnlyReason!=='PUBLISHED'" ref="embeddedInfo" :locked="locked||finalFlow.busy.value||p.busy.value||publicationPending" presentation="final" :meeting-id="meetingId" :eligible="true" @saved="emit('infoSaved');p.reload()"/><template v-else><label class="form-label">会议名称 <span class="required">*</span></label><input class="input" readonly :value="shownInfo?.name??''"/><label class="form-label mt16">会议日期</label><input class="input" type="date" readonly :value="shownInfo?.occurredOn??''"/><label class="form-label mt16">会议分类 <span class="required">*</span></label><input class="input" readonly :value="categoryLabels?.[shownInfo?.category??'']??(shownInfo?.category?'分类暂不可读取':'未选择')"/><label class="form-label mt16">会议摘要</label><div class="confirm-description">{{shownInfo?.summary||'暂无会议摘要'}}</div><label class="form-label mt16">参会人</label><div class="confirm-participants"><span v-for="person in shownInfo?.confirmedRoster??[]" :key="person.memberId" class="tag orange">{{person.displayName}}</span><span v-if="!shownInfo?.confirmedRoster?.length" class="muted">{{shownInfo?.confirmedRosterId?'已确认空名单':'暂未添加参会人'}}</span></div><p class="small muted mt12">最终确认使用已保存信息与已确认名单。</p></template></div></section><section class="card ac-confirm-preview"><div class="card-h"><h3 class="card-t">纪要预览</h3></div><div class="card-p ac-confirm-body"><template v-if="previewBody"><pre>{{previewBody.title+'\n\n'+previewBody.body}}</pre><details class="confirm-outcomes mt16"><summary>核对成果与来源</summary><div v-for="(items,category) in previewElements" :key="category" class="mt16"><h4>{{outcomeLabels[category]??category}}</h4><p v-if="!items.length" class="small muted">暂无相关内容</p><p v-for="item in items" :key="item.id" class="confirm-outcome-text">{{item.body}} <button v-if="owner" class="btn sm ghost" :disabled="finalFlow.busy.value||p.busy.value" @click="processCheck({kind:'outcome',targetId:item.id})">查看来源与审阅</button></p></div><div class="mt16"><h4>背景引用</h4><p v-if="!previewBackground.length" class="small muted">当前版本没有独立背景摘录</p><p v-for="note in previewBackground" :key="note.id" class="confirm-outcome-text">{{note.body}} <button v-for="locatorId in note.locatorIds" :key="locatorId" class="btn sm ghost" @click="processCheck({kind:'background',locatorId})">查看背景来源</button></p></div></details></template><div v-else class="empty">尚无已保存纪要</div></div></section></div>
 <FinalConfirmationChecks v-if="owner" :checks="checks" :busy="p.reading.value||p.busy.value||finalFlow.busy.value" @process="processCheck" @retry="p.reload"/>
 <details v-if="owner&&optionalReviews.length" class="small mt16 optional-reviews"><summary>补充审阅记录（可选）</summary><p class="muted mt8">选择随最终确认冻结的已通过记录；必需审阅会自动纳入。</p><label v-for="review in optionalReviews" :key="review.id" class="optional-review"><input v-model="optional" type="checkbox" :value="review.id" :disabled="finalFlow.busy.value||p.busy.value||!!p.final.value?.confirmation"/> {{optionalLabel(review)}}</label></details>
 <footer v-if="owner" ref="fixedDock" class="acf-dock"><div class="acf-inner"><div class="acf-hint confirmation-hint">{{p.final.value?.confirmation?'当前版本已最终确认。':'最终确认将保存会议信息、确认参会名单并更新访问权限；会议名称和分类必填，日期、摘要和参会名单可空。'}}</div><div class="acf-actions"><button class="btn" :disabled="finalFlow.busy.value||p.busy.value" @click="emit('navigate','minutes')">返回纪要编辑</button><button v-if="p.final.value?.confirmation" class="btn primary" :disabled="embeddedInfo?.dirty||finalFlow.busy.value||p.busy.value" @click="emit('navigate','publish')">继续发布 ›</button><button v-else class="btn primary" :disabled="locked||p.busy.value||finalFlow.busy.value||p.reading.value||(!canPrepareFinal||!embeddedInfo?.canPrepare)" @click="confirmFinal">最终确认并继续发布</button></div></div></footer></template>
 <template v-if="stage==='publish'"><div class="two-col ac-publish-grid"><section class="card ac-publish-location"><div class="card-h"><h3 class="card-t">选择发布位置</h3></div><div class="card-p">
 <div class="pub-location-search"><div class="search-box"><Icon name="search" :size="13"/><input v-model="librarySearch" class="input" aria-label="搜索发布知识库" placeholder="搜索知识库名称或说明" :disabled="configurationLocked"/><button type="button" class="pub-search-clear" :hidden="!librarySearch" aria-label="清空知识库搜索" title="清空搜索" @click="librarySearch='' "><Icon name="x" :size="13"/></button></div></div>
 <p class="small muted pub-location-count">{{destinations.libraries.value?.hasMore?'已加载知识库':'知识库'}} {{visibleLibraries.length}} 个</p><p v-if="destinations.busy.value" class="small muted" role="status">正在读取目录…</p>
 <div class="pub-location-list"><div v-for="lib in visibleLibraries" :key="lib.id" class="ac-publish-library" :class="{'is-current':selectedDestination?.libraryId===lib.id}"><button type="button" class="radio-row pub-location-item" :class="{sel:selectedDestination?.libraryId===lib.id&&!selectedDestination.path.length}" :aria-pressed="selectedDestination?.libraryId===lib.id&&!selectedDestination.path.length" :disabled="configurationLocked||lib.canPublish===false" @click="destinations.selectLibrary(lib)"><span class="radio-dot"></span><span class="pub-library-copy"><b>{{lib.name}}</b><small>{{lib.description||'暂无说明'}}</small><small>{{lib.visibility||'可见范围待提供方核实'}} · {{lib.canPublish===false?lib.unavailableReason:'具备发布权限'}}</small></span></button>
 <div v-if="selectedDestination?.libraryId===lib.id" class="ac-publish-library-folders"><ul v-if="destinations.rows(lib).length" class="tree"><li v-for="row in destinations.rows(lib)" :key="row.folder.id" :style="{marginLeft:row.depth*22+'px'}"><div class="tree-node" :class="{sel:selectedDestination?.folderId===row.folder.id}"><button type="button" class="t-caret folder-expand" :class="{open:row.expanded}" :disabled="configurationLocked||row.knownEmpty" :aria-label="(row.expanded?'收起':'展开')+'文件夹 '+row.folder.name" :aria-expanded="row.expanded" @click="destinations.toggle(lib,row.folder)">{{row.knownEmpty?'':'▸'}}</button><button type="button" class="folder-select" :disabled="configurationLocked" :aria-pressed="selectedDestination?.folderId===row.folder.id" @click="destinations.selectFolder(lib,row.folder,row.path)"><Icon name="folder" :size="14"/> {{row.folder.name}}</button></div><button v-if="destinations.branch(lib,row.folder.id)?.expanded&&destinations.branch(lib,row.folder.id)?.page.hasMore" type="button" class="btn sm" :disabled="destinations.busy.value||configurationLocked" @click="destinations.loadBranch(lib,row.folder.id,destinations.branch(lib,row.folder.id)!.page.nextCursor)">更多子文件夹</button></li></ul><p v-else-if="destinations.branch(lib,lib.rootFolderId)&&!destinations.busy.value&&!destinations.error.value" class="small muted">暂无文件夹，可直接发布到此知识库。</p><button v-if="destinations.branch(lib,lib.rootFolderId)?.page.hasMore" type="button" class="btn sm" :disabled="destinations.busy.value||configurationLocked" @click="destinations.loadBranch(lib,lib.rootFolderId,destinations.branch(lib,lib.rootFolderId)!.page.nextCursor)">更多文件夹</button></div></div>
 <p v-if="destinations.libraries.value&&!visibleLibraries.length" class="empty">未找到匹配的知识库，请调整搜索条件。</p></div>
 <button v-if="destinations.libraries.value?.hasMore" type="button" class="btn sm" :disabled="destinations.busy.value||configurationLocked" @click="destinations.loadLibraries(destinations.libraries.value.nextCursor)">更多知识库</button>
 <p v-if="destinations.error.value" role="alert">{{destinations.error.value instanceof Error?destinations.error.value.message:'目录读取失败。'}} <button type="button" class="btn sm" :disabled="destinations.busy.value||configurationLocked" @click="destinations.retry()">重试读取目录</button></p><p v-if="destinations.storageMessage.value" class="small muted mt12">{{destinations.storageMessage.value}}</p>
 <p class="small muted mt12">文件夹继承知识库权限；仅可选择已有文件夹，不能在此创建、修改或删除。</p></div></section>
 <div class="grid" style="gap:16px"><section class="card"><div class="card-h"><h3 class="card-t">发布配置</h3></div><div class="card-p"><div class="field"><label>发布路径</label><div class="card card-p pub-selected-path"><b>{{selectedPath}}</b></div></div><div class="field"><label for="publication-frozen-title">文档标题</label><input id="publication-frozen-title" class="input" readonly :value="p.final.value?.body?.title??''" title="标题与最终确认一致；如需修改，请返回纪要编辑并重新确认。"/></div>
 <div class="field"><label for="publication-tags">标签</label><input id="publication-tags" class="input" v-model="configuration.tagsText.value" :disabled="configurationLocked" placeholder="用逗号分隔标签"/><p v-if="configuration.current.value" class="small muted mt8">用于文档检索，与会议分类分别保存。最多 {{configuration.current.value.tagRules.maxCount}} 个，每个最多 {{configuration.current.value.tagRules.maxLength}} 个字符。</p></div>
 <p v-if="configuration.busy.value" class="small muted" role="status">正在读取或保存发布配置…</p><p v-if="configuration.error.value" role="alert">{{configurationError}} <button class="btn sm" :disabled="configuration.busy.value||publicationPending" @click="loadConfiguration">重新读取配置</button><button v-if="selectedDestination" class="btn sm" :disabled="configuration.busy.value||publicationPending" @click="saveConfiguration">重试保存</button></p><p v-if="publicationSaveMessage" class="small muted" role="status">{{publicationSaveMessage}}</p>
 <div class="banner info pub-permission-hint"><Icon name="lock" :size="15"/> 正式文档继承目标知识库权限；原录音、会议转写和引用材料仍分别校验访问权限。</div><div class="divider"></div><div class="grid pub-frozen-facts"><div class="between"><span class="muted">来源会议</span><span class="mono small">{{meetingId}}</span></div><div class="between"><span class="muted">证据完整性</span><span class="tag" :class="p.final.value?.provenanceVerified?'green':'amber'">{{p.final.value?.provenanceVerified?'冻结版本与来源已核验':'请先完成最终确认'}}</span></div><div class="between"><span class="muted">确认编号</span><span class="mono small">{{p.final.value?.confirmation?.id}}</span></div><div class="between"><span class="muted">可见范围</span><span class="tag navy">{{visibility}}</span></div></div><div class="mt12"><button type="button" class="btn" :disabled="!p.final.value?.confirmation||!p.final.value.body||p.busy.value" @click="openPreview"><Icon name="eye" :size="14"/> 最终文档预览</button></div></div></section></div></div>
 <dialog ref="previewDialog" class="publication-check-mask mask" role="presentation" @cancel.self.prevent="previewDialog?.close()" @click.self="previewDialog?.close()"><section class="modal lg" role="dialog" aria-modal="true" aria-labelledby="publication-preview-title"><header class="modal-h"><h3 id="publication-preview-title" class="m-t">最终文档预览（发布版）</h3><button type="button" class="m-x" aria-label="关闭最终文档预览" @click="previewDialog?.close()"><Icon name="x" :size="18"/></button></header><div class="modal-b"><template v-if="p.final.value?.body&&p.final.value.information"><div class="publication-preview-content"><pre class="publication-frozen-text">{{p.final.value.body.title+'\n\n'+p.final.value.body.body}}</pre><dl class="publication-preview-metadata"><dt>发布路径</dt><dd>{{selectedPath}}</dd><dt>可见范围</dt><dd>{{visibility}}</dd><dt>标签</dt><dd>{{publicationPending?submittedConfiguration?.tags.join('、')||'未设置':configuration.tagsText.value||'未设置'}}</dd><dt>会议分类</dt><dd>{{props.categoryLabels?.[p.final.value.information.category??'']??p.final.value.information.category}}</dd><dt>会议名称</dt><dd>{{p.final.value.information.name}}</dd><dt>会议日期</dt><dd>{{p.final.value.information.occurredOn??'未填写'}}</dd><dt>会议摘要</dt><dd>{{p.final.value.information.summary??'未填写'}}</dd><dt>参会人</dt><dd>{{p.final.value.information.roster.map(person=>person.displayName).join('、')||'空名单'}}</dd><dt>最终确认编号</dt><dd class="mono">{{p.final.value.confirmation?.id}}</dd></dl><details class="mt16"><summary>来源关系与保留说明</summary><p>正文与成果使用最终确认快照；待确认事项和分歧保留原有性质，知识背景不作为会议结论。</p><div v-for="(items,category) in p.final.value.elements" :key="category" class="mt12"><h4>{{outcomeLabels[category]??category}}</h4><p v-for="item in items" :key="item.id">{{item.body}} <button class="btn sm ghost" @click="previewDialog?.close();processCheck({kind:'outcome',targetId:item.id})">查看来源与审阅</button></p></div><div v-for="note in previewBackground" :key="note.id" class="mt12"><p>{{note.body}}</p><button v-for="locatorId in note.locatorIds" :key="locatorId" class="btn sm ghost" @click="previewDialog?.close();processCheck({kind:'background',locatorId})">查看背景来源</button></div></details></div></template><p v-else role="alert">最终确认预览暂不可读取，请关闭后重试。</p></div><footer class="modal-f"><button type="button" class="btn primary" @click="previewDialog?.close()">关闭预览</button></footer></section></dialog>
 <footer v-if="owner" ref="fixedDock" class="acf-dock"><div class="acf-inner"><span class="acf-hint">{{publicationPending?'任务绑定提交时的确认和配置；离开页面不取消任务。':selectedDestination?'请核对发布配置，确认后发布到知识库。':'请选择发布知识库，也可继续选择库内文件夹。'}}</span><div class="acf-actions"><button v-if="status?.allowedActions.includes('RECOVER_LOCAL')" class="btn" :disabled="locked||p.busy.value" @click="recover('RECOVER_LOCAL')">恢复未发送任务</button><button v-if="status?.allowedActions.includes('RETRY_ZERO_EFFECT')" class="btn" :disabled="locked||p.busy.value||configuration.busy.value||configurationChanged" @click="recover('RETRY_ZERO_EFFECT')">按原配置重试</button><button v-if="!status||canReconfigure" class="btn primary" :disabled="!destinations.canSubmit.value||configurationLocked||!configuration.current.value||!p.final.value?.confirmation" @click="publish">{{status?'按当前配置重新提交':'发布到知识库'}}</button><button v-else class="btn primary" :disabled="p.reading.value||p.busy.value" @click="p.reload">查询发布状态</button></div></div></footer></template>
 <article v-if="status" class="card publication-status"><div class="between"><h3>{{stateLabels[status.rawState]??'发布状态'}}</h3><button class="btn sm" :disabled="p.busy.value" @click="run(p.reload)">刷新最终状态</button></div><p class="small muted">{{remoteLabels[status.remoteOutcome]??status.remoteOutcome}} · {{applicationLabels[status.applicationOutcome]??status.applicationOutcome}}</p><p v-if="status.phase" role="status">{{phaseLabels[status.phase]}}</p><dl class="publication-result-facts"><dt>发布位置</dt><dd><a v-if="libraryLink" :href="libraryLink" target="_blank" rel="noopener">{{selectedPath}}</a><template v-else>{{selectedPath}}</template></dd><dt>可见范围</dt><dd>{{visibility}}</dd><template v-if="status.documentId"><dt>文档编号</dt><dd class="mono">{{status.documentId}}</dd><dt>发布版本</dt><dd>V{{status.documentVersion}}</dd></template><template v-if="status.publishedBy"><dt>发布人</dt><dd>{{status.publishedBy}}</dd></template><template v-if="status.publishedAt"><dt>发布时间（UTC）</dt><dd>{{status.publishedAt}}</dd></template><dt>确认编号</dt><dd class="mono">{{status.confirmationId}}</dd></dl><p v-if="status.failureCode" role="alert">{{failureLabels[status.failureCode]??'发布未完成，请核对当前确认、来源及目标位置。'}} <span class="small">错误编号：{{status.failureCode}}</span></p><p v-if="status.remoteOutcome==='UNKNOWN'">远端结果尚未确定。请刷新查询，当前不能再次发送。</p><p v-if="status.applicationOutcome==='FENCED_MANUAL'">该发布关联需要人工处理，当前页面只提供结果查看。</p><a v-if="status.officialDocumentUrl" class="btn primary mt12" :href="status.officialDocumentUrl" target="_blank" rel="noopener">查看正式文档 ↗</a><p v-else class="small muted">正式文档入口当前不可用。</p><button v-if="canManage&&status.rawState==='SUCCEEDED'&&p.final.value?.observation&&app.governanceCommands" class="btn mt12" @click="app.governanceCommands.open(status.publicationId,p.final.value!.observation!.revisionToken)">撤回 / 废止与治理历史</button><details v-if="owner" class="mt12"><summary @click="loadAttempts()">发布尝试记录</summary><ul v-if="attempts"><li v-for="a in attempts.items" :key="a.attemptId">{{attemptLabels[a.kind]??'发布处理'}} · {{remoteLabels[a.remoteOutcome]??'等待处理'}} · {{applicationLabels[a.applicationOutcome]??'等待应用'}} · {{a.createdAt}}</li></ul><button v-if="attempts?.hasMore" class="btn sm" @click="loadAttempts(attempts.nextCursor)">下一页尝试</button></details></article>
 <p v-if="p.command.state.value==='ACKNOWLEDGED'" class="small muted">{{p.command.snapshot.value?.operation==='FINAL_CONFIRM'?'已收到原最终确认回执，冻结版本以当前读取结果为准。':'已收到原操作回执；发布是否完成以上方当前状态为准。'}}</p><button v-if="p.command.snapshot.value&&['PREPARED','UNCERTAIN'].includes(p.command.state.value)" class="btn" :disabled="p.busy.value" @click="run(p.retry)">{{p.command.snapshot.value.operation.startsWith('PUBLICATION_')?'查回原发布状态':'查回原最终确认'}}</button><button v-if="['CONFLICT','REJECTED'].includes(p.command.state.value)" class="btn" @click="p.reset();p.reload()">重新读取后再决定</button>
<Teleport to="body"><dialog ref="successDialog" class="publication-check-mask mask" role="presentation" @cancel.self.prevent="successDialog?.close()" @click.self="successDialog?.close()"><section class="modal pub-success-modal" role="dialog" aria-modal="true" aria-labelledby="publication-success-title"><header class="modal-h"><button type="button" class="m-x" aria-label="关闭发布成功提示" @click="successDialog?.close()"><Icon name="x" :size="18"/></button></header><div class="modal-b"><div class="pub-success-body"><div class="pub-success-icon" aria-hidden="true"><svg viewBox="0 0 64 64" width="64" height="64"><circle cx="32" cy="32" r="30" fill="#E6F7ED"/><path d="m19 32 9 9 18-19" fill="none" stroke="#00B255" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></div><h2 id="publication-success-title">发布成功</h2><p>会议纪要已发布到知识库，已发布会议不支持修改。</p><p v-if="libraryLink" class="mt12"><a class="pub-success-path" :href="libraryLink" target="_blank" rel="noopener">{{selectedPath}} ↗</a></p><p v-else class="small muted mt12">发布编号：<span class="mono">{{status?.publicationId}}</span></p><p v-if="status?.officialDocumentUrl" class="mt12"><a class="pub-success-path" :href="status.officialDocumentUrl" target="_blank" rel="noopener">查看正式文档</a></p></div></div><footer class="modal-f"><button type="button" class="btn primary" @click="successDialog?.close()">知道了</button></footer></section></dialog></Teleport></section></template>
